function skillContentChanged(existing, data) {
  if (!existing || !existing.id) return true;
  var fields = ['name', 'category', 'prompt', 'scenario', 'scope', 'content', 'output'];
  return fields.some(function (key) {
    return String(existing[key] || '') !== String((data && data[key]) || '');
  });
}

function saveSkill(data, targetStatus) {
  var list = getCustomSkills();
  var now = new Date();
  var id = (data && data.id) || ('sk_custom_' + now.getTime());
  var status = targetStatus === 'enabled' ? 'enabled' : 'draft';
  var existing = skillById(id) || {};
  var version = existing.version || 'v0.1.0';
  var versionBumped = false;
  var unchanged = false;
  if (data && data.id && existing.status === 'enabled' && targetStatus === 'enabled') {
    if (skillContentChanged(existing, data)) {
      version = incrementPatchVersion(existing.version);
      versionBumped = true;
    } else {
      unchanged = true;
    }
  }

next._versionBumped = versionBumped;
next._unchanged = unchanged;
list = list.filter(function (s) { return s.id !== id; });

function openForm(id, presetData) {
  editingId = id || null;
  var s = id ? Proto.skillById(id) : null;
  var pre = presetData || null;
  var enableBtn = document.getElementById('skillFormSaveEnable');
  var defaultLabel = enableBtn.getAttribute('data-default-label') || '启用';
  document.getElementById('skillFormTitle').textContent = id ? '编辑 Skill' : '新建 Skill';
  var subEl = document.getElementById('skillFormSub');
  if (pre) {
    subEl.textContent = '以下内容由 SKILL.md 解析，请确认后保存。';
    enableBtn.textContent = defaultLabel;
  } else if (s && s.status === 'enabled') {
    subEl.textContent = '已启用 Skill 编辑后点击「保存」；仅在有内容变更时发布新版本（补丁位 +1）。';
    enableBtn.textContent = '保存';
  } else {
    subEl.textContent = '新建资源只发生在智能体开发平台；启用后才可被运营平台选择。';
    enableBtn.textContent = defaultLabel;
  }
  document.getElementById('skillFormImportBanner').style.display = pre ? 'block' : 'none';
  document.getElementById('skillFormName').value     = pre ? pre.name     : (s ? s.name     : '');
  document.getElementById('skillFormCategory').value = pre ? pre.category : (s ? s.category : '输出规范');
  document.getElementById('skillFormDesc').value     = pre ? pre.prompt   : (s ? (s.prompt || '') : '');
  document.getElementById('skillFormScenario').value = pre ? pre.scenario : (s ? s.scenario : '');
  document.getElementById('skillFormScope').value    = pre ? pre.scope    : (s ? s.scope    : '全公司');
  document.getElementById('skillFormContent').value  = pre ? pre.content  : (s ? (s.content || '') : '');
  document.getElementById('skillFormOutput').value   = pre ? pre.output   : (s ? (s.output  || '') : '');
  var draftBtn = document.getElementById('skillFormSaveDraft');
  if (s && s.status === 'enabled') {
    draftBtn.disabled = true;
    draftBtn.title = '已启用 Skill 请直接保存变更';
  } else {
    draftBtn.disabled = false;
    draftBtn.title = '';
  }
  formModal.classList.add('active');
}

