function previewFile(fileName, extra) {
  document.getElementById('skillImportPreview').style.display = 'block';
  document.getElementById('skillImportPreviewMeta').textContent =
    fileName + (extra ? ' · ' + extra : '') + ' · 已解析';
  document.getElementById('skillImportNext').disabled = false;
  importedDraft = Proto.mockParseSkillFile(fileName);
}

function pickImportSource() {
  var fileInput = document.getElementById('skillImportFile');
  var folderInput = document.getElementById('skillImportFolder');
  fileInput.value = '';
  folderInput.value = '';
  fileInput.onchange = function (e) {
    var f = e.target.files && e.target.files[0];
    if (!f) {
      folderInput.click();
      return;
    }
    previewFile(f.name);
  };
  folderInput.onchange = function (e) {
    var files = e.target.files;
    if (!files || !files.length) return;
    var folderName = (files[0].webkitRelativePath || files[0].name).split('/')[0];
    previewFile(folderName + '/SKILL.md', files.length + ' 个文件');
  };
  fileInput.click();
}

