function startCountdown(targetUrl) {
  var sec = 3;
  var el = document.getElementById('countdown');
  var url = targetUrl || configPageUrl();
  var link = document.querySelector('#state-success a[href*="05-agent-detail"]');
  if (link) link.href = url;
  var footLink = document.querySelector('#footerSuccess a');
  if (footLink) footLink.href = url;
  clearInterval(countdownTimer);
  countdownTimer = setInterval(function() {
    sec--;
    if (el) el.textContent = sec;
    if (sec <= 0) { clearInterval(countdownTimer); window.location.href = url; }
  }, 1000);
}

