function bindTabs(containerSel) {
  var root = document.querySelector(containerSel);
  if (!root) return;
  root.querySelectorAll('[data-tab]').forEach(function (btn) {
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var tab = btn.getAttribute('data-tab');
      root.querySelectorAll('[data-tab]').forEach(function (b) { b.classList.remove('active'); });
      btn.classList.add('active');
      document.querySelectorAll('.agent-tab-panel').forEach(function (p) {
        p.classList.toggle('active', p.id === 'tab-' + tab);
      });
      if (history.replaceState) {
        var u = new URL(window.location.href);
        u.searchParams.set('tab', tab);
        history.replaceState(null, '', u);
      }
    });
  });
  var initial = params().get('tab');
  if (initial) {
    var t = root.querySelector('[data-tab="' + initial + '"]');
    if (t) t.click();
  }
}

input.old_string:
function bindTabs(containerSel) {
  var root = document.querySelector(containerSel);
  if (!root) return;
  function inSetup() {
    return document.documentElement.classList.contains('mode-setup') ||
      document.body.classList.contains('mode-setup');
  }
  root.querySelectorAll('[data-tab]').forEach(function (btn) {
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      var tab = btn.getAttribute('data-tab');
      if (inSetup() && tab !== 'config') return;
      root.querySelectorAll('[data-tab]').forEach(function (b) { b.classList.remove('active'); });
      btn.classList.add('active');
      document.querySelectorAll('.agent-tab-panel').forEach(function (p) {
        p.classList.toggle('active', p.id === 'tab-' + tab);
      });
      if (history.replaceState) {
        var u = new URL(window.location.href);
        u.searchParams.set('tab', tab);
        history.replaceState(null, '', u);
      }
    });
  });
  var initial = params().get('tab');
  if (initial && !(inSetup() && initial !== 'config')) {
    var t = root.querySelector('[data-tab="' + initial + '"]');
    if (t) t.click();
  }
}

