input.contents:
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');

const checks = [
  ['06-dev-editor.html', ['dev-col-header', 'devEditorRoot', '返回运营配置'], ['保存并返回', 'startCountdown']],
  ['04-create-modal.html', ['返回列表', '进入配置', 'updateSuccessLinks'], ['startCountdown', '秒后进入']],
  ['05-agent-detail.html', ['first-config-banner', 'bindSegmented'], [' disabled>']],
  ['assets/proto.js', ['initCrossLinks', 'wireDevPlatformRows'], ['inSetup() && tab']],
  ['assets/editor-shell.js', ['bindSegmented'], []],
  ['assets/agent-core-config.js', ['GPT-4o mini'], ['disabled>']],
];

let fail = 0;
for (const [file, must, mustNot] of checks) {
  const t = fs.readFileSync(path.join(root, file), 'utf8');
  for (const m of must) {
    if (!t.includes(m)) {
      console.error('MISSING', file, m);
      fail++;
    }
  }
  for (const m of mustNot) {
    if (t.includes(m)) {
      console.error('UNWANTED', file, m);
      fail++;
    }
  }
}

const editor = fs.readFileSync(path.join(root, '06-dev-editor.html'), 'utf8');
if (!editor.includes('class="dev-col"')) {
  console.error('MISSING 06-dev-editor.html static dev-col');
  fail++;
}

console.log(fail ? 'FAILED ' + fail : 'ALL CHECKS PASSED');
process.exit(fail ? 1 : 0);

