function saveDraft(manual) {
  var now = new Date().toLocaleString('zh-CN', { hour12: false });
  var promptEl = document.getElementById('promptText');
  Proto.setState({
    draftPrompt: promptEl ? promptEl.value : '',
    lastSavedAt: Date.now(),
    lastSaveMode: manual ? 'manual' : 'auto'
  });
  draftDirty = false;
  var hint = manual ? '已保存 ' + now.split(' ')[1] : '已自动保存 ' + now.split(' ')[1];
  document.getElementById('saveHint').textContent = hint;
  document.getElementById('barSaved').textContent = (manual ? '上次保存：' : '上次自动保存：') + now;
  if (manual) Proto.toast('已保存');
  if (Proto.isFirstConfig() && manual) {
    Proto.finishFirstConfig();
    document.body.classList.remove('mode-setup');
    document.documentElement.classList.remove('mode-setup');
    var fb = document.getElementById('firstConfigBanner');
    if (fb) fb.style.display = 'none';
  }
  refreshStateUi();
}

var draftDirty = false;
var autoSaveTimer = null;
function markDraftDirty() {
  draftDirty = true;
  document.getElementById('saveHint').textContent = '未保存';
  clearTimeout(autoSaveTimer);
  autoSaveTimer = setTimeout(function () { saveDraft(false); }, 2000);
}
function bindAutoSave() {
  var promptEl = document.getElementById('promptText');
  if (promptEl) {
    var st = Proto.getState();
    if (st.draftPrompt) promptEl.value = st.draftPrompt;
    else if (st.desc && Proto.params().get('new') === '1') promptEl.value = st.desc;
    promptEl.addEventListener('input', markDraftDirty);
  }
  var root = document.getElementById('opsEditorRoot');
  if (root) {
    root.addEventListener('input', markDraftDirty);
    root.addEventListener('change', markDraftDirty);
  }
  var stSaved = Proto.getState();
  if (stSaved.lastSavedAt) {
    var savedAt = new Date(stSaved.lastSavedAt).toLocaleString('zh-CN', { hour12: false });
    var prefix = stSaved.lastSaveMode === 'manual' ? '上次保存：' : '上次自动保存：';
    document.getElementById('barSaved').textContent = prefix + savedAt;
    document.getElementById('saveHint').textContent = prefix.replace('上次', '已').replace('：', ' ') + savedAt.split(' ')[1];
  }
}
bindAutoSave();

