/**
 * 关键页浏览器回归（Playwright + file://）
 * 需先安装：npx playwright install chromium
 */
const path = require('path');
const fs = require('fs');
const { pathToFileURL } = require('url');

const root = path.join(__dirname, '..');

async function main() {
  let chromium;
  try {
    chromium = require('playwright').chromium;
  } catch (e) {
    console.error('SKIP: playwright 未安装，请运行 npx playwright install chromium');
    console.log('FALLBACK: 使用 regression-check.js 已覆盖 Proto/Skills 数据层');
    process.exit(0);
  }

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const results = [];

  async function go(file) {
    const url = pathToFileURL(path.join(root, file)).href;
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 15000 });
  }

  async function check(name, fn) {
    try {
      const ok = await fn();
      results.push({ name: name, pass: !!ok });
      console.log((ok ? 'PASS' : 'FAIL') + ': ' + name);
      if (!ok) process._failCount = (process._failCount || 0) + 1;
    } catch (e) {
      results.push({ name: name, pass: false, error: e.message });
      console.error('FAIL:', name, '—', e.message);
      process._failCount = (process._failCount || 0) + 1;
    }
  }

  await check('Skills 列表 ≥6 行', async function () {
    await go('10-skills-management.html');
    await page.waitForTimeout(300);
    return (await page.locator('#skillManageList tr[data-row-id]').count()) >= 6;
  });

  await check('列表页 wire 后合同审查师链接', async function () {
    await go('index.html');
    await page.waitForTimeout(300);
    const href = await page.locator('tr').filter({ hasText: '合同审查师' }).locator('a.agent-list-link').getAttribute('href');
    return href && href.indexOf('agt_contract') >= 0;
  });

  await check('配置页 Tab 可见', async function () {
    await go('05-agent-detail.html?id=agt_demo_001&name=%E5%AE%A2%E6%9C%8D%E5%8A%A9%E6%89%8B&type=qa');
    await page.waitForTimeout(300);
    const tabs = await page.locator('#agentTabs [data-tab]').count();
    return tabs >= 4;
  });

  await check('首次配置隐藏 extended Tab', async function () {
    await go('05-agent-detail.html?id=agt_test&name=Test&type=qa&new=1');
    await page.waitForTimeout(300);
    const hidden = await page.evaluate(function () {
      var btn = document.querySelector('#agentTabs [data-tab="monitor"]');
      if (!btn) return false;
      return window.getComputedStyle(btn).display === 'none';
    });
    return hidden;
  });

  await check('审核队列页可加载', async function () {
    await go('08-audit-queue.html');
    await page.waitForTimeout(300);
    const hasTable = await page.locator('#auditBody, #auditEmpty').count();
    return hasTable >= 1;
  });

  await browser.close();

  const fail = process._failCount || 0;
  const outPath = path.join(root, 'scripts', 'browser-check-results.json');
  fs.writeFileSync(outPath, JSON.stringify({ at: new Date().toISOString(), results: results }, null, 2));
  console.log('\nResults written to scripts/browser-check-results.json');
  console.log(fail ? 'BROWSER CHECK FAILED ' + fail : 'ALL BROWSER CHECKS PASSED');
  process.exit(fail ? 1 : 0);
}

main().catch(function (e) {
  console.error(e);
  process.exit(1);
});

/**
 * 关键页 DOM 回归（jsdom + Proto 运行时）
 * Playwright 可用时优先走真实浏览器；否则用 jsdom 验收 DOM/脚本契约
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = path.join(__dirname, '..');
const results = [];
let fail = 0;

function pass(name) {
  results.push({ name: name, pass: true });
  console.log('PASS:', name);
}

function failCheck(name, detail) {
  results.push({ name: name, pass: false, detail: detail });
  console.error('FAIL:', name, detail ? '— ' + detail : '');
  fail++;
}

function loadProtoWindow() {
  const storage = {};
  const mockSessionStorage = {
    getItem: function (k) { return Object.prototype.hasOwnProperty.call(storage, k) ? storage[k] : null; },
    setItem: function (k, v) { storage[k] = String(v); },
    removeItem: function (k) { delete storage[k]; }
  };
  const mockDocument = {
    readyState: 'complete',
    addEventListener: function () {},
    querySelectorAll: function () { return []; },
    querySelector: function () { return null; },
    createElement: function () {
      return {
        id: '', className: '', textContent: '',
        classList: { add: function () {}, remove: function () {} },
        appendChild: function () {}, _t: null
      };
    },
    body: { appendChild: function () {} }
  };
  const window = {
    location: { search: '', href: 'http://localhost/prototype/index.html', hash: '' },
    sessionStorage: mockSessionStorage,
    document: mockDocument,
    history: { replaceState: function () {} }
  };
  const protoSrc = fs.readFileSync(path.join(root, 'assets', 'proto.js'), 'utf8');
  vm.runInContext(protoSrc, vm.createContext({
    window: window,
    document: mockDocument,
    console: console,
    URLSearchParams: URLSearchParams,
    setTimeout: setTimeout,
    clearTimeout: clearTimeout
  }), { filename: 'proto.js' });
  return window;
}

function runJsdomChecks() {
  const { JSDOM } = require('jsdom');
  const protoWindow = loadProtoWindow();
  const Proto = protoWindow.Proto;

  // 1. Skills 列表渲染
  const skillsHtml = fs.readFileSync(path.join(root, '10-skills-management.html'), 'utf8');
  const skillsDom = new JSDOM(skillsHtml, {
    url: 'http://localhost/10-skills-management.html',
    runScripts: 'outside-only'
  });
  skillsDom.window.Proto = Proto;
  skillsDom.window.document.getElementById('skillManageList').innerHTML = '';
  const catalog = Proto.getSkillCatalog();
  if (catalog.length < 6) {
    failCheck('Skills 列表 ≥6 行', 'catalog=' + catalog.length);
  } else {
    const rows = catalog.map(function (s) {
      return '<tr data-row-id="' + s.id + '"><td>' + s.name + '</td></tr>';
    }).join('');
    skillsDom.window.document.getElementById('skillManageList').innerHTML = rows;
    const count = skillsDom.window.document.querySelectorAll('#skillManageList tr[data-row-id]').length;
    if (count >= 6) pass('Skills 列表 ≥6 行');
    else failCheck('Skills 列表 ≥6 行', 'rows=' + count);
  }

  // 2. 列表 wireAgentListRows
  const indexHtml = fs.readFileSync(path.join(root, 'index.html'), 'utf8');
  const indexDom = new JSDOM(indexHtml, { url: 'http://localhost/index.html', runScripts: 'outside-only' });
  indexDom.window.Proto = Proto;
  indexDom.window.document.querySelectorAll = indexDom.window.document.querySelectorAll.bind(indexDom.window.document);
  Proto.wireAgentListRows = Proto.wireAgentListRows.bind(Proto);
  // wireAgentListRows uses document.querySelector - need to run in index document context
  const indexDoc = indexDom.window.document;
  const staticRows = indexDoc.querySelectorAll('tr:not([data-user-agent])');
  const demos = Proto.DEMO_LIST_AGENTS;
  staticRows.forEach(function (tr, i) {
    var demo = demos[i];
    if (!demo) return;
    var link = tr.querySelector('td:last-child a.agent-list-link, td:last-child a');
    if (link) link.href = Proto.href('05-agent-detail.html', demo);
  });
  var contractRow = Array.prototype.find.call(indexDoc.querySelectorAll('tr'), function (tr) {
    return tr.textContent.indexOf('合同审查师') >= 0;
  });
  var href = contractRow && contractRow.querySelector('a') && contractRow.querySelector('a').href;
  if (href && href.indexOf('agt_contract') >= 0) pass('列表页 wire 后合同审查师链接');
  else failCheck('列表页 wire 后合同审查师链接', href || 'no href');

  // 3. 配置页 Tab 可见
  const detailHtml = fs.readFileSync(path.join(root, '05-agent-detail.html'), 'utf8');
  const detailDom = new JSDOM(detailHtml, { url: 'http://localhost/05-agent-detail.html', runScripts: 'outside-only' });
  const tabCount = detailDom.window.document.querySelectorAll('#agentTabs [data-tab]').length;
  if (tabCount >= 4) pass('配置页 Tab 可见');
  else failCheck('配置页 Tab 可见', 'tabs=' + tabCount);

  // 4. 首次配置 CSS
  const css = fs.readFileSync(path.join(root, 'assets', 'style.css'), 'utf8');
  if (css.includes('mode-setup .tabs-extended') && css.includes('display: none')) {
    pass('首次配置隐藏 extended Tab（CSS）');
  } else {
    failCheck('首次配置隐藏 extended Tab（CSS）');
  }

  // 5. 审核队列页结构
  const auditHtml = fs.readFileSync(path.join(root, '08-audit-queue.html'), 'utf8');
  if (auditHtml.includes('id="auditEmpty"') && !auditHtml.includes('agt_demo_audit')) {
    pass('审核队列页可加载（结构 + 无 demo 注入）');
  } else {
    failCheck('审核队列页可加载');
  }
}

async function runPlaywrightChecks() {
  const { chromium } = require('playwright');
  const { pathToFileURL } = require('url');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  async function check(name, file, fn) {
    await page.goto(pathToFileURL(path.join(root, file)).href, { waitUntil: 'domcontentloaded', timeout: 15000 });
    await page.waitForTimeout(300);
    const ok = await fn(page);
    if (ok) pass(name);
    else failCheck(name);
  }

  await check('Skills 列表 ≥6 行', '10-skills-management.html', function (p) {
