function Install-GithubZip($repo, $destName) {
  $dest = Join-Path $vendor $destName
  if (Test-Path $dest) { Remove-Item $dest -Recurse -Force }
  $zip = Join-Path $env:TEMP "$destName.zip"
  $urls = @(
    "https://github.com/$repo/archive/refs/heads/main.zip",
    "https://github.com/$repo/archive/refs/heads/master.zip"
  )
  foreach ($url in $urls) {
    try {
      Invoke-WebRequest -Uri $url -OutFile $zip -UseBasicParsing -TimeoutSec 120
      if ((Get-Item $zip).Length -gt 1000) { break }
    } catch { continue }
  }
  Expand-Archive -Path $zip -DestinationPath $env:TEMP -Force
  $extracted = Get-ChildItem $env:TEMP -Directory | Where-Object { $_.Name -like "$($destName)*" -or $_.Name -like "*$(Split-Path $repo -Leaf)*" } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  if (-not $extracted) {
    $extracted = Get-ChildItem $env:TEMP -Directory | Where-Object { $_.Name -match 'ai-coding-ok|agent-verifier|agent-skills' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  }
  Move-Item $extracted.FullName $dest -Force
  Remove-Item $zip -Force -ErrorAction SilentlyContinue
  Write-Output "Installed $destName -> $dest"
}

