function loadProtoIntoWindow(window, sessionStorage) {
  const mockDocument = {
    readyState: 'complete',
    body: { classList: { add: function () {}, remove: function () {}, toggle: function () {} } },
    documentElement: { classList: { add: function () {}, remove: function () {}, toggle: function () {} } },
    addEventListener: function () {},
    querySelector: function () { return null; },
    querySelectorAll: function () { return []; },
    getElementById: function () { return null; },
    createElement: function () {
      return {
        id: '', className: '', textContent: '', innerHTML: '',
        classList: { add: function () {}, remove: function () {}, toggle: function () {} },
        appendChild: function () {}, setAttribute: function () {}, _t: null
      };
    }
  };
  window.sessionStorage = sessionStorage;
  window.document = mockDocument;
  window.history = { replaceState: function () {} };
  window.AgentCoreConfig = { wireDevLinks: function () {} };

  const protoSrc = fs.readFileSync(path.join(root, 'assets', 'proto.js'), 'utf8');
