/**
 * 打包完整性检查：16 页 HTML、相对链接/资源、无仓库外引用
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const EXPECTED_HTML_COUNT = 16;
const REDIRECT_PAGES = ['03-agent-center.html', '08-agent-monitor.html'];
const results = { passed: [], failed: [], htmlFiles: [] };

function pass(msg) {
  results.passed.push(msg);
  console.log('PASS:', msg);
}

function fail(msg) {
  results.failed.push(msg);
  console.error('FAIL:', msg);
}

function resolveLocal(baseDir, ref) {
  if (!ref || ref.startsWith('#') || ref.startsWith('http://') || ref.startsWith('https://') ||
      ref.startsWith('mailto:') || ref.startsWith('javascript:') || ref.startsWith('data:')) {
    return null;
  }
  var clean = ref.split('?')[0].split('#')[0];
  if (!clean || clean === '/') return null;
  return path.normalize(path.join(baseDir, clean));
}

function extractRefs(html) {
  var refs = [];
  var re = /(?:href|src)=["']([^"']+)["']/gi;
  var m;
  while ((m = re.exec(html)) !== null) refs.push(m[1]);
  return refs;
}

console.log('=== package-check ===\n');

var htmlFiles = fs.readdirSync(root).filter(function (f) {
  return f.endsWith('.html');
}).sort();

results.htmlFiles = htmlFiles;

if (htmlFiles.length === EXPECTED_HTML_COUNT) {
  pass('HTML 页面数量 = ' + EXPECTED_HTML_COUNT);
} else {
  fail('HTML 页面数量应为 ' + EXPECTED_HTML_COUNT + '，实际 ' + htmlFiles.length);
}

var requiredAssets = ['assets/proto.js', 'assets/style.css'];
requiredAssets.forEach(function (rel) {
  if (fs.existsSync(path.join(root, rel))) pass('共享资源存在 → ' + rel);
  else fail('缺失共享资源 → ' + rel);
});

htmlFiles.forEach(function (file) {
  var filePath = path.join(root, file);
  var html = fs.readFileSync(filePath, 'utf8');
  var baseDir = path.dirname(filePath);
  var isRedirect = REDIRECT_PAGES.indexOf(file) >= 0;

  if (!isRedirect) {
    if (html.indexOf('assets/style.css') >= 0 || html.indexOf("href=\"assets/style.css\"") >= 0) {
      pass(file + ' → 引用 style.css');
    } else {
      fail(file + ' → 未引用 assets/style.css');
    }
    if (html.indexOf('assets/proto.js') >= 0 || html.indexOf("src=\"assets/proto.js\"") >= 0) {
