    } else if (file === 'figma-skills-board.html') {
      pass(file + ' → figma 板（proto 可选）');
    } else {
      fail(file + ' → 未引用 assets/proto.js');
    }
  }

  extractRefs(html).forEach(function (ref) {
    if (ref.indexOf('..') === 0) {
      fail(file + ' → 指向仓库外路径: ' + ref);
      return;
    }
    if (/^\.\.\//.test(ref) || ref.indexOf('../skills') >= 0 || ref.indexOf('../design') >= 0) {
      fail(file + ' → 外部依赖: ' + ref);
      return;
    }
    var resolved = resolveLocal(baseDir, ref);
    if (!resolved) return;
    if (!fs.existsSync(resolved)) {
      fail(file + ' → 链接目标不存在: ' + ref);
    }
  });
});

